using Microsoft.EntityFrameworkCore;
namespace TheBarcode.Api;
public static class AccountingJournalBuilder
{
 private static readonly SemaphoreSlim SyncLock = new(1, 1);
 public static async Task Ensure(AppDbContext db,bool demo){await SyncLock.WaitAsync();try{var a=await db.LedgerAccounts.Where(x=>x.IsDemo==demo&&x.Active).ToDictionaryAsync(x=>x.Code);if(a.Count==0)return;var generated=await db.JournalEntries.Include(x=>x.Lines).Where(x=>x.IsDemo==demo&&x.SourceId!=null).ToListAsync();var bySource=generated.Where(x=>x.SourceId!=null).ToDictionary(x=>x.SourceId!);var sales=await db.Sales.AsNoTracking().Include(x=>x.Items).Include(x=>x.Payments).Where(x=>x.IsDemo==demo&&x.Status!="Held"&&x.Status!="PendingApproval").ToListAsync();foreach(var s in sales){var source=$"sale:{s.Id}";var e=bySource.GetValueOrDefault(source);if(e is null){e=new JournalEntry{SourceType="Sale",SourceId=source,Memo="",IsDemo=demo};db.JournalEntries.Add(e);}else ResetLines(db,e);e.Date=DateOnly.FromDateTime(s.OccurredAt.LocalDateTime);e.Memo=$"Sale {s.ReceiptNumber}";foreach(var p in s.Payments)e.Lines.Add(new JournalLine{AccountId=p.Method.Equals("M-Pesa",StringComparison.OrdinalIgnoreCase)?a["1010"].Id:a["1000"].Id,Description=p.Method,Debit=p.Amount});var paid=s.Payments.Sum(x=>x.Amount);if(s.Total>paid)e.Lines.Add(new JournalLine{AccountId=a["1100"].Id,Description="Customer receivable",Debit=s.Total-paid});e.Lines.Add(new JournalLine{AccountId=a["4000"].Id,Description="Sales revenue",Credit=s.Total});var cost=s.Items.Sum(x=>x.UnitCost*x.Quantity);if(cost>0){e.Lines.Add(new JournalLine{AccountId=a["5000"].Id,Description="Cost of goods sold",Debit=cost});e.Lines.Add(new JournalLine{AccountId=a["1200"].Id,Description="Inventory issued",Credit=cost});}}var expenses=await db.Expenses.AsNoTracking().Where(x=>x.IsDemo==demo&&x.Active&&x.Status=="Approved").ToListAsync();foreach(var x in expenses){var source=$"expense:{x.Id}";var e=bySource.GetValueOrDefault(source);if(e is null){e=new JournalEntry{SourceType="Expense",SourceId=source,Memo="",IsDemo=demo};db.JournalEntries.Add(e);}else ResetLines(db,e);e.Date=x.Date;e.Memo=x.Description;e.Lines.Add(new JournalLine{AccountId=a["6000"].Id,Description=x.Category,Debit=x.Amount});var paid=Math.Min(x.Amount,x.PaidAmount);if(paid>0)e.Lines.Add(new JournalLine{AccountId=a["1000"].Id,Description=x.Method,Credit=paid});if(x.Amount>paid)e.Lines.Add(new JournalLine{AccountId=a["2000"].Id,Description="Supplier payable",Credit=x.Amount-paid});}await db.SaveChangesAsync();}finally{SyncLock.Release();}}
 static void ResetLines(AppDbContext db,JournalEntry e){if(e.Lines.Count==0)return;db.JournalLines.RemoveRange(e.Lines);e.Lines.Clear();}
}
